let current = 'es';
try { if (globalThis.localStorage?.getItem('pc-lang') === 'en') current = 'en'; } catch { /* Almacenamiento no disponible. */ }
export const lang = () => current;
// Formato numérico: México usa punto decimal y coma de miles (59.7 %, 5,183,723)
export const locale = () => current === 'en' ? 'en-US' : 'es-MX';
export function t(key, vars = {}) {
  return (DICT[current][key] ?? DICT.es[key] ?? key).replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(vars, name) ? String(vars[name]) : match);
}
export function applyStatic(root = document) {
  for (const [data, attr] of [['data-i18n', null], ['data-i18n-ph', 'placeholder'], ['data-i18n-aria', 'aria-label'], ['data-i18n-title', 'title']]) {
    const nodes = [...(root.matches?.(`[${data}]`) ? [root] : []), ...root.querySelectorAll(`[${data}]`)];
    for (const node of nodes) { const value = t(node.getAttribute(data)); if (attr) node.setAttribute(attr, value); else node.textContent = value; }
  }
}
export function setLang(l) {
  current = l === 'en' ? 'en' : 'es';
  try { globalThis.localStorage?.setItem('pc-lang', current); } catch { /* Almacenamiento no disponible. */ }
  if (typeof document !== 'undefined') {
    document.documentElement.lang = current;
    document.title = t('meta.title');
    document.querySelector('meta[name="description"]')?.setAttribute('content', t('meta.description'));
    applyStatic();
    document.dispatchEvent(new Event('pc-language-change'));
  }
}

// Resta las cifras a una décima que se muestran en pantalla.
export const diff1 = (a, b) => { const r1 = x => Math.round(x * 10) / 10; return Math.round((r1(a) - r1(b)) * 10) / 10; };
